let fleet=[],locations=[],mode='self',category='All';
const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₹'+n.toLocaleString('en-IN');
const rateFor=car=>mode==='self'?car.selfRate:car.driverRate;
function localDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
const today=new Date(),tomorrow=new Date(today);tomorrow.setDate(today.getDate()+1);$('start-date').min=localDate(today);$('start-date').value=localDate(today);$('end-date').min=localDate(tomorrow);$('end-date').value=localDate(tomorrow);$('year').textContent=today.getFullYear();
function validDates(){const start=$('start-date').value,end=$('end-date').value;if(!start||!end||start<localDate(new Date())||end<=start){$('search-error').textContent='Choose a pick-up date from today and a return date after pick-up.';return false;}$('search-error').textContent='';return true;}
function visibleCars(){return fleet.filter(c=>(category==='All'||c.category===category)&&c.locationIds.includes($('city').value)&&(mode==='self'?c.selfEnabled:c.driverEnabled));}
function render(){const list=visibleCars(),city=locations.find(l=>l.id===$('city').value)?.name||'No active locations';$('result-count').textContent=`${list.length} ${list.length===1?'car':'cars'} · ${city} · ${mode==='self'?'Self-drive':'With a chauffeur'}`;$('cars').innerHTML=list.length?list.map(c=>`<article class="car-card"><div class="car-image">${c.image?`<img src="${esc(c.image)}" alt="${esc(c.name)}" loading="lazy">`:''}<span class="car-tag">${esc(c.category.toUpperCase())}</span></div><div class="car-body"><div class="car-title"><h3>${esc(c.name)}</h3></div><div class="car-specs"><span>♙ ${c.seats} seats</span><span>◈ ${esc(c.category)}</span></div><div class="car-bottom"><div class="price">${rateFor(c)==null?'Request a quote':money(rateFor(c))+'<small> / day</small>'}</div><button class="ride-button" data-book="${esc(c.id)}">View ride</button></div></div></article>`).join(''):'<div class="empty">No cars are currently listed for this city and rental type. Try another selection or contact GoRide.</div>';}
function renderLocations(){const previous=$('city').value;$('city').innerHTML=locations.map(l=>`<option value="${esc(l.id)}">${esc(l.name)}</option>`).join('');if(locations.some(l=>l.id===previous))$('city').value=previous;$('city-grid').innerHTML=locations.map((l,i)=>`<button class="city-card" data-city="${esc(l.id)}"><span class="city-number">${String(i+1).padStart(2,'0')} / GORIDE</span><h3>${esc(l.name)}</h3><p>Your next journey starts here.</p><span class="city-action">Explore cars</span></button>`).join('');const names=locations.map(l=>l.name);$('hero-cities').textContent=names.join(' · ').toUpperCase();$('footer-cities').textContent=names.join(' / ');$('cities-title').innerHTML=locations.length===3?'Three cities.<br>Countless detours<span>.</span>':'More places.<br>Countless detours<span>.</span>';$('find-button').disabled=!locations.length;}
function renderFilters(){const values=['All',...new Set(fleet.map(c=>c.category))];if(!values.includes(category))category='All';$('category-filters').innerHTML=values.map(c=>`<button class="filter ${category===c?'active':''}" data-category="${esc(c)}" aria-pressed="${category===c}">${c==='All'?'All cars':esc(c==='Hatchback'?'Hatchbacks':c+'s')}</button>`).join('');}
function renderCredits(){const items=fleet.filter(c=>c.imageCredit).map(c=>`<span>${esc(c.name)} photo: ${c.imageSource?`<a href="${esc(c.imageSource)}" target="_blank" rel="noopener noreferrer">${esc(c.imageCredit)}</a>`:esc(c.imageCredit)}${c.imageLicense?', '+esc(c.imageLicense):''}, cropped to fit.</span>`);$('photo-credits').innerHTML=items.join(' ')+' <a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noopener noreferrer">CC BY 3.0 license</a>. Hero: <a href="https://unsplash.com/photos/black-sedan-FMbWFDiVRPs" target="_blank" rel="noopener noreferrer">Samuele Errico Piccarini / Unsplash</a>.';}
async function loadCatalog(){try{const response=await fetch('/api/catalog',{cache:'no-store'});if(!response.ok)throw Error('Catalogue unavailable');const data=await response.json();fleet=data.cars;locations=data.locations;renderLocations();renderFilters();renderCredits();render();$('catalog-error').hidden=true;}catch{$('catalog-error').hidden=false;if(!fleet.length)$('cars').innerHTML='<div class="empty">Our cars could not be loaded. <button class="ride-button" id="retry-catalog">Try again</button> or call GoRide on 86102 35694.</div>';}}
document.querySelectorAll('.mode').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.mode;document.querySelectorAll('.mode').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});render();}));$('category-filters').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b)return;category=b.dataset.category;renderFilters();render();});$('city').addEventListener('change',render);
$('start-date').addEventListener('change',()=>{const d=new Date($('start-date').value+'T12:00:00');if(Number.isNaN(d.getTime()))return;d.setDate(d.getDate()+1);$('end-date').min=localDate(d);if($('end-date').value<localDate(d))$('end-date').value=localDate(d);});$('search-form').addEventListener('submit',e=>{e.preventDefault();if(validDates()){render();$('fleet').scrollIntoView({behavior:'smooth'});}});$('city-grid').addEventListener('click',e=>{const b=e.target.closest('[data-city]');if(!b)return;$('city').value=b.dataset.city;render();$('search').scrollIntoView({behavior:'smooth'});});
function openTrip(id){if(!validDates()){$('search').scrollIntoView({behavior:'smooth'});return;}const car=visibleCars().find(c=>c.id===id);if(!car)return;const days=Math.round((Date.parse($('end-date').value)-Date.parse($('start-date').value))/86400000),rate=rateFor(car),city=locations.find(l=>l.id===$('city').value)?.name;const fmt=s=>new Date(s+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'});const row=(label,value)=>`<div class="trip-row"><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`;$('booking-content').innerHTML=`<div class="dialog-eyebrow">YOUR TRIP, AT A GLANCE</div><h2>${esc(car.name)}</h2><p style="color:var(--muted);font-size:14px">${mode==='self'?'Self-drive. Your own pace.':'With a chauffeur. Enjoy the journey.'}</p><div class="trip-summary">${row('Pick-up city',city)}${row('Pick-up',fmt($('start-date').value))}${row('Return',fmt($('end-date').value))}${row('Duration',days+' '+(days===1?'day':'days'))}${row(rate==null?'Rental price':'Daily base rate',rate==null?'Request a quote':money(rate))}${rate==null?'':row('Base rental estimate',money(rate*days))}${car.deposit==null?'':row('Security deposit (separate)',money(car.deposit))}</div>${car.notes?`<p class="dialog-note">${esc(car.notes).replace(/\n/g,'<br>')}</p>`:''}<p class="dialog-note"><strong>This is a trip preview.</strong> No car is reserved and no payment is taken. Base rental estimates exclude any unlisted taxes, fuel, extra kilometres and driver allowances. Confirm your total, availability and terms with GoRide.</p><a class="primary" id="quote-link" target="_blank" rel="noopener noreferrer">Request quote on WhatsApp</a><a class="primary" href="/account?car=${encodeURIComponent(car.id)}&location=${encodeURIComponent($('city').value)}" style="display:block;margin-top:12px;text-align:center">Send a booking request</a><button class="ride-button" id="done-preview" style="width:100%;margin-top:12px">Close preview</button>`;const message=`Hi GoRide, I would like a quote for ${car.name} in ${city}, ${mode==='self'?'self-drive':'with a chauffeur'}, from ${fmt($('start-date').value)} to ${fmt($('end-date').value)} (${days} ${days===1?'day':'days'}).${rate==null?'':' Listed base rental: '+money(rate*days)+'.'} Please confirm availability, total price, deposit and inclusions.`;$('quote-link').href='https://wa.me/919100852287?text='+encodeURIComponent(message);$('booking-dialog').showModal();$('done-preview').onclick=()=> $('booking-dialog').close();}
$('cars').addEventListener('click',e=>{if(e.target.closest('#retry-catalog'))loadCatalog();const b=e.target.closest('[data-book]');if(b)openTrip(b.dataset.book);});$('close-dialog').onclick=()=> $('booking-dialog').close();$('booking-dialog').addEventListener('click',e=>{if(e.target===$('booking-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
fetch('/assets/images.json').then(r=>r.json()).then(images=>{$('hero-image').style.backgroundImage=`url("${images.hero.url}")`;}).catch(()=>{});loadCatalog();window.addEventListener('focus',()=>{if(!$('booking-dialog').open)loadCatalog();});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'configure_car_search',title:'Configure car search',description:'Set GoRide city, rental mode and car category filters. Does not create a reservation.',inputSchema:{type:'object',properties:{city:{type:'string'},mode:{type:'string',enum:['self','driver']},category:{type:'string'}},required:['city','mode','category'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const l=locations.find(l=>l.id===input?.city||l.name===input?.city);if(!l||!['self','driver'].includes(input.mode)||!['All',...fleet.map(c=>c.category)].includes(input.category))throw Error('Invalid search filters');$('city').value=l.id;mode=input.mode;category=input.category;document.querySelector(`[data-mode="${mode}"]`).click();renderFilters();render();return {city:l.name,mode,category,resultCount:visibleCars().length,reservationCreated:false};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
